ATTACH TABLE _ UUID 'e82365e7-7105-44b9-9845-392cef0ea1e3'
(
    `source_path` String CODEC(ZSTD(3)),
    `import_id` String CODEC(ZSTD(3)),
    `segment_end` UInt64 CODEC(Delta(8), ZSTD(1)),
    `line_no` UInt64 CODEC(Delta(8), ZSTD(1)),
    `event_key` String CODEC(ZSTD(3)),
    `timestamp` Nullable(String) CODEC(ZSTD(1)),
    `date_key` String CODEC(ZSTD(1)),
    `week_key` String CODEC(ZSTD(1)),
    `month_key` String CODEC(ZSTD(1)),
    `year_key` String CODEC(ZSTD(1)),
    `provider` LowCardinality(String) CODEC(ZSTD(1)),
    `model` String CODEC(ZSTD(3)),
    `project` String CODEC(ZSTD(3)),
    `effort` LowCardinality(String) CODEC(ZSTD(1)),
    `service_tier` LowCardinality(String) DEFAULT 'unknown' CODEC(ZSTD(1)),
    `service_mode` LowCardinality(String) DEFAULT 'unknown' CODEC(ZSTD(1)),
    `agent` LowCardinality(String) DEFAULT 'unknown' CODEC(ZSTD(1)),
    `input` UInt64 CODEC(Delta(8), ZSTD(1)),
    `cache_create_5m` UInt64 CODEC(Delta(8), ZSTD(1)),
    `cache_create_30m` UInt64 CODEC(Delta(8), ZSTD(1)),
    `cache_create_1h` UInt64 CODEC(Delta(8), ZSTD(1)),
    `cache_read` UInt64 CODEC(Delta(8), ZSTD(1)),
    `output` UInt64 CODEC(Delta(8), ZSTD(1)),
    `reasoning_output` UInt64 CODEC(Delta(8), ZSTD(1)),
    `context_window` UInt64 CODEC(Delta(8), ZSTD(1)),
    `priced` UInt8 CODEC(T64, ZSTD(1)),
    `cost_usd` Float64 CODEC(Gorilla(8), ZSTD(1)),
    `reasoning_cost_usd` Float64 CODEC(Gorilla(8), ZSTD(1)),
    `cost_input_usd` Float64 CODEC(Gorilla(8), ZSTD(1)),
    `cost_cache_create_5m_usd` Float64 CODEC(Gorilla(8), ZSTD(1)),
    `cost_cache_create_30m_usd` Float64 CODEC(Gorilla(8), ZSTD(1)),
    `cost_cache_create_1h_usd` Float64 CODEC(Gorilla(8), ZSTD(1)),
    `cost_cache_read_usd` Float64 CODEC(Gorilla(8), ZSTD(1)),
    `cost_output_usd` Float64 CODEC(Gorilla(8), ZSTD(1)),
    `visible_input_chars` UInt64 CODEC(Delta(8), ZSTD(1)),
    `visible_output_chars` UInt64 CODEC(Delta(8), ZSTD(1)),
    `visible_total_chars` UInt64 CODEC(Delta(8), ZSTD(1)),
    `visible_chars_per_token` Float64 CODEC(Gorilla(8), ZSTD(1))
)
ENGINE = MergeTree
ORDER BY (date_key, source_path, line_no)
SETTINGS index_granularity = 8192
